syntax:
class Base {
public:
  virtual void foo() { /* ... */ }
  virtual void bar() { /* ... */ }
};

class Derived : public Base {
public:
  void foo() override { /* ... */ }
  void baz() { /* ... */ }
};

int main() {
  Derived d;
  void (Derived::*ptr)() = &Derived::foo; // Pointer-to-member function
  (d.*ptr)(); // Member function call using pointer-to-member
  return 0;
}

code_example:
#include <iostream>
class Base {
public:
  virtual void foo() { std::cout << "Base::foo\n"; }
  virtual void bar() { std::cout << "Base::bar\n"; }
};

class Derived : public Base {
public:
  void foo() override { std::cout << "Derived::foo\n"; }
  void baz() { std::cout << "Derived::baz\n"; }
};

int main() {
  Derived d;
  void (Derived::*ptr)() = &Derived::foo; // Pointer-to-member function
  (d.*ptr)(); // Member function call
  void (Base::*ptr2)() = &Base::bar;
  (d.*ptr2)(); // Member function call using Base pointer-to-member on Derived object
  return 0;
}
